<script lang="ts">
 import type {Command} from '../lib/types';
 import {newCommandId,withCommandId,StaleConflictError,UnknownCommitResultError} from '../lib/repository';
 let {complexId,commit}:{complexId:string;commit:(c:Command)=>Promise<void>}=$props();
 let value=$state<number|undefined>();let date=$state('');let source=$state('');let busy=$state(false);let error=$state('');let success=$state(false);
 let intent:{key:string;id:string;command:Command}|undefined;
 async function submit(){if(busy)return;busy=true;error='';success=false;try{if(value==null||!date||!source.trim())throw new Error('Укажите значение, дату и документальный источник.');const key=JSON.stringify([value,date,source]);if(intent&&intent.key!==key)throw new Error('Повторите прежнее наблюдение с теми же полями до получения подтверждения.');intent??={key,id:newCommandId(),command:{type:'readiness',zkId:complexId,value,date,source}};await commit(withCommandId(intent.command,intent.id));intent=undefined;success=true;}catch(e){if(!(e instanceof StaleConflictError||e instanceof UnknownCommitResultError))intent=undefined;error=e instanceof Error?e.message:String(e);}finally{busy=false;}}
</script>
<details class="mt-5"><summary>Зафиксировать документальную готовность</summary><form class="space-y-3 mt-4" onsubmit={e=>{e.preventDefault();void submit();}}><label>Готовность по документу, %<input required type="number" min="0" max="100" step="any" bind:value={value}/></label><label>Дата наблюдения<input required type="date" bind:value={date}/></label><label>Источник измеренной готовности<input required bind:value={source}/></label><p class="muted">Сохраняется наблюдение с источником. Разрыв готовности подтверждается отдельным фактом R5 в «Проверке».</p>{#if error}<p class="error" role="alert">{error}</p>{/if}{#if success}<p class="success" role="status">Наблюдение сохранено. Баллы требуют отдельной проверки факта.</p>{/if}<button disabled={busy}>Сохранить наблюдение</button></form></details>
